#endif

#include "gx_validation_wrapper.h"
#include "demo_guix_standalone_binres_load_extended_unicode_32bpp.c"
#include "gx_validation_binres_glyph_range.h"

static VOID control_thread_entry(ULONG input)
{
int  failed_tests = 0;
UINT size;

    EXPECT_EQ(GX_SUCCESS, binres_font_size_get(0x41, GX_MAX_GLYPH_CODE, 0, 1, &size));
    EXPECT_EQ(GX_INVALID_FONT, binres_font_size_get(0x41, GX_MAX_GLYPH_CODE + 1, 0, 1, &size));

    if (failed_tests == 0)
    {
        printf("Guix Test:   guix_binres_glyph_code_bound_ex_unicode_no_output...............................Success!\n");
        exit(0);
    }
    else
    {
        printf("Guix Test:   guix_binres_glyph_code_bound_ex_unicode_no_output................................Failed!\n");
        exit(1);
    }
}
